('hq-0064-1','math','高中',13,'hs-kp-0064','single_choice',0.75,'半径 3、圆心角 90° 的弧长 l = ？','[{"key":"A","text":"3×π/2"},{"key":"B","text":"3"},{"key":"C","text":"270"},{"key":"D","text":"π"}]','A','l = rθ = 3×90°(弧度) = 3×π/2','template-hs','approved','通用');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version) VALUES
('hq-0065-1','math','高中',13,'hs-kp-0065','single_choice',0.35,'角 α 终边过点 (5,5)，sinα = ？','[{"key":"A","text":"5/7.0710678118654755"},{"key":"B","text":"5/7.0710678118654755"},{"key":"C","text":"5/5"},{"key":"D","text":"7.0710678118654755/5"}]','A','r=√(5²+5²)=7.0710678118654755，sinα=y/r=5/7.0710678118654755','template-hs','approved','通用');
