('hq-0066-1','math','高中',13,'hs-kp-0066','single_choice',0.45,'角 α 在第二象限，sinα 的符号是？','[{"key":"A","text":"正"},{"key":"B","text":"负"},{"key":"C","text":"0"},{"key":"D","text":"不确定"}]','A','第二象限 sin>0','template-hs','approved','通用');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version) VALUES
('hq-0067-1','math','高中',13,'hs-kp-0067','single_choice',0.55,'sinα=3/5，α 为锐角，则 cosα = ？','[{"key":"A","text":"4/5"},{"key":"B","text":"3/5"},{"key":"C","text":"5/4"},{"key":"D","text":"5/3"}]','A','cosα=√(1-sin²α)=√(1-9/25)=4/5','template-hs','approved','通用');
