('hq-0068-1','math','高中',13,'hs-kp-0068','single_choice',0.65,'sin(210°) = ？','[{"key":"A","text":"-1/2"},{"key":"B","text":"1/2"},{"key":"C","text":"0"},{"key":"D","text":"1"}]','A','sin(210°)=-sin30°=-1/2（诱导公式）','template-hs','approved','通用');
