('hq-0070-1','math','高中',13,'hs-kp-0070','single_choice',0.35,'y=sin x 图像横坐标缩短到 1/4 → y=？','[{"key":"A","text":"y=sin(4x)"},{"key":"B","text":"y=sin(x/4)"},{"key":"C","text":"y=4sin x"},{"key":"D","text":"y=sin(x+4)"}]','A','横缩：x→4x，即 y=sin(4x)','template-hs','approved','通用');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version) VALUES
('hq-0071-1','math','高中',13,'hs-kp-0071','single_choice',0.45,'asin x + bcos x = R·sin(x+φ)，R = ？ (a=4,b=5)','[{"key":"A","text":"√41"},{"key":"B","text":"9"},{"key":"C","text":"20"},{"key":"D","text":"1"}]','A','R=√(a²+b²)=√(16+25)=√41','template-hs','approved','通用');
