('hq-0072-1','math','高中',13,'hs-kp-0072','single_choice',0.55,'sin60°cos30°+cos60°sin30° = sin90° = ？','[{"key":"A","text":"1"},{"key":"B","text":"0.5"},{"key":"C","text":"0"},{"key":"D","text":"2"}]','A','sin60°cos30°+cos60°sin30°=sin(60°+30°)=sin90°=1','template-hs','approved','通用');